"""Archive immutable control reports with exact reconstruction checks."""
import hashlib,json,subprocess
from pathlib import Path
root=Path('/Users/baai/.codex/worktrees/native-compiler-routing-synthesis/FlagQuantum')
out=root/'docs/development/evidence';writes={}
for draw in ('inspected','fresh'):
    raw=Path(f'/private/tmp/fq-native-negative-{draw}-20261123.json').read_bytes()
    report=json.loads(raw)
    assert report['completed'] and len(report['rows'])==120
    payloads=report['payloads'];report['payloads']={}
    chunks=[];chunk={}
    for key,value in payloads.items():
        if chunk and len(json.dumps({**chunk,key:value},separators=(',',':')).encode())>1100000:
            chunks.append(chunk);chunk={}
        chunk[key]=value
    if chunk:chunks.append(chunk)
    refs=[]
    for i,chunk in enumerate(chunks):
        name=f'native-negative-screen-{draw}-payloads-{i:02d}.json'
        data=(json.dumps(chunk,separators=(',',':'),allow_nan=False)+'\n').encode()
        writes[name]=data;refs.append({'name':name,'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)})
    tree=report['manifest'].pop('production_tree')
    envelope={'original_report_sha256':hashlib.sha256(raw).hexdigest(),'original_report_bytes':len(raw),'payload_files':refs,'report':report,'production_tree_object':{'git_object_type':'tree','sha1_octets':list(bytes.fromhex(tree))},'representation_note':'Restore report.manifest.production_tree from production_tree_object after source_commit, then restore payloads from payload_files and encode with indent=2 and one trailing newline. The original report bytes and SHA-256 must match.','archive_driver_source':Path(__file__).read_text()}
    writes[f'native-negative-screen-{draw}.json']=(json.dumps(envelope,indent=2,allow_nan=False)+'\n').encode()
for category in ('replay','resources'):
    raw=Path(f'/private/tmp/fq-native-negative-{category}-20261123.json').read_bytes()
    if category=='replay':writes[f'native-negative-screen-{category}.json']=raw;continue
    report=json.loads(raw);tree=report['manifest'].pop('production_tree')
    envelope={'original_report_sha256':hashlib.sha256(raw).hexdigest(),'original_report_bytes':len(raw),'report':report,'production_tree_object':{'git_object_type':'tree','sha1_octets':list(bytes.fromhex(tree))},'representation_note':'Restore report.manifest.production_tree from production_tree_object after source_commit, then encode with indent=2 and one trailing newline. The original report bytes and SHA-256 must match.'}
    writes[f'native-negative-screen-{category}.json']=(json.dumps(envelope,indent=2,allow_nan=False)+'\n').encode()
for name,data in writes.items():
    if 'payloads' in name or 'replay' in name:continue
    envelope=json.loads(data);report=envelope['report'];manifest={}
    for key,value in report['manifest'].items():
        manifest[key]=value
        if key=='source_commit':manifest['production_tree']=bytes(envelope['production_tree_object']['sha1_octets']).hex()
    report['manifest']=manifest
    if 'payload_files' in envelope:
        payloads={}
        for ref in envelope['payload_files']:
            chunk=writes[ref['name']]
            assert len(chunk)==ref['bytes'] and hashlib.sha256(chunk).hexdigest()==ref['sha256']
            payloads.update(json.loads(chunk))
        report['payloads']=payloads
    restored=(json.dumps(report,indent=2,allow_nan=False)+'\n').encode()
    assert len(restored)==envelope['original_report_bytes'] and hashlib.sha256(restored).hexdigest()==envelope['original_report_sha256']
paths=['docs/development/evidence/'+name for name in writes]
subprocess.run(['/Users/baai/Documents/liuwei/sdkbench/.venv/bin/python','tools/check_team_scope.py','--team','compiler','--files',*paths],cwd=root,check=True,timeout=20)
for name,data in writes.items():
    with (out/name).open('xb') as stream:stream.write(data)
    print(name,len(data),hashlib.sha256(data).hexdigest())
